    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Furthermore, areas of uncertainty related to the scarcity of studies carried out with EMS professionals were identified since the COVID-19 pandemic is a recent event, never before experienced, which limits the scientific literature on this phenomenon.",
      "reason": "The text explicitly describes the current state of knowledge (limited scientific literature due to the recent nature of the pandemic) and the important uncertainty (scarcity of studies on EMS professionals)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Because the field of COVID-19 research is moving relatively quickly and new knowledge evidence is continually emerging, an update plan for this systematic review is needed in order to provide convincing evidence for HPs and policymakers.",
      "reason": "The text explains the importance and need for the review, specifically noting the rapidly evolving nature of COVID-19 research and the need to provide evidence for health professionals and policymakers."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided text does not mention the existence of other similar systematic reviews, so this conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is not a review of intervention effects; it is a review of the psychological impact of the pandemic on health professionals."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is not a review of complex interventions or delivery contexts requiring a logic model."
    }
  ],
  "confidence": 100
