{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "The selected research studies had to meet the following inclusion criteria: (1) being original, (2) based on qualitative and/or quantitative methods, (3) with any methodological design, (4) submitted for peer-review, (5) published in English, Spanish, French, Italian or Portuguese, (6) completed after December 2019, (7) without geographic limitation, (8) with at least the abstract available, and (9) that in their results evaluated the impact of possible exposure to SARS-CoV-2 on levels of stress, anxiety, depression and/or self-efficacy of the HPs who were working in public, private, or voluntary out-of-hospital EMS during the COVID-19 pandemic or identified factors related positively or negatively with these levels or compared them with those obtained in other working environments and/or professional categories.",
      "reason": "The manuscript explicitly lists the inclusion criteria, covering study design, setting, and population."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "The selected research studies had to meet the following inclusion criteria: ... (4) submitted for peer-review, (5) published in English, Spanish, French, Italian or Portuguese, (6) completed after December 2019",
      "reason": "The manuscript specifies report characteristics including publication status (peer-reviewed), language, and date of completion."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not explicitly distinguish between studies excluded because outcomes were not measured versus studies excluded because results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "The designs of most of the selected research ( n = 16) were of the descriptive crosssectional type [52,54-57,59-69], except in the case of the 4 remaining studies in which a qualitative methodology was used [51,53,58,70].",
      "reason": "The review specifies the groups used for the narrative synthesis (cross-sectional studies vs. qualitative studies)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "The selected research studies had to meet the following inclusion criteria: ... (6) completed after December 2019 ... Critical Appraisal Tools from JBI ... were used to evaluate the scientifictechnical quality of the selected articles ... High methodological quality was established for the inclusion of studies in the review.",
      "reason": "The manuscript provides rationales for restrictions, such as the date restriction (due to the COVID-19 pandemic) and the quality restriction (to ensure scientific-technical quality)."
    }
  ],
  "confidence": 100
}

